insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('orientation', 'cardio', 'Take the Oath', 'Finish your baseline and do 10+ minutes of easy movement you enjoy. Start where you are.', array['walking','hiking','running','cycling','swimming','mobility','strength','custom']::text[], 'easy', 100, 10, '[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}]'::jsonb, '{"noGym":"Walk around the block.","indoorOnly":"March in place or follow a mobility routine.","limitedTime":"10 minutes is the whole quest.","mobility":"Gentle seated or standing mobility counts."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('strength', 'strength', 'Strength session', 'Squat, push, pull and hinge patterns with controlled reps. Stop 2–3 reps before failure and keep form crisp.', array['strength','obstacle']::text[], 'moderate', 100, null, '[{"type":"cardio","label":"10-minute easy walk","allowedActivityTypes":["walking","hiking"],"minDurationSeconds":600}]'::jsonb, '{"noGym":"Bodyweight squats, incline push-ups, table rows, hip hinges.","indoorOnly":"Same session at home.","limitedTime":"One round of each pattern counts if you hit the minimum time.","mobility":"Box squats and wall push-ups; skip any painful movement."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('aerobic', 'cardio', 'Zone 2 endurance', 'Steady effort at a conversational pace — walk, jog, bike or swim. You should finish feeling you could do more.', array['walking','hiking','running','cycling','swimming']::text[], 'easy', 100, null, '[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}]'::jsonb, '{"noGym":"Brisk walk outdoors.","indoorOnly":"Stationary bike, treadmill or stairs.","limitedTime":"The minimum time counts.","mobility":"Low impact: bike, pool or water walking."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('tempo', 'cardio', 'Tempo intervals', 'Warm up 10 minutes, then 3–5 × 3 minutes comfortably hard with 2 minutes easy between. Controlled, never all-out.', array['walking','hiking','running','cycling','swimming']::text[], 'hard', 80, null, '[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}]'::jsonb, '{"noGym":"Brisk uphill walking intervals.","indoorOnly":"Bike or treadmill intervals.","limitedTime":"Three intervals is a full session.","mobility":"Swap for an easy Zone 2 session if anything aches."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('mobility', 'mobility', 'Mobility & core', 'Slow, controlled range-of-motion work for hips, spine and shoulders. Breathe and stay pain-free.', array['mobility']::text[], 'easy', 50, null, '[{"type":"cardio","label":"10-minute easy walk","allowedActivityTypes":["walking","hiking"],"minDurationSeconds":600}]'::jsonb, '{"noGym":"Floor only — no equipment needed.","indoorOnly":"Same session indoors.","limitedTime":"Ten minutes counts.","mobility":"Seated or supported versions are fine."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('recovery', 'recovery', 'Planned recovery', 'Rest is training. Light mobility or an easy stroll, or simply check in that you rested.', array['recovery','mobility','walking']::text[], 'rest', 0, 0, '[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}]'::jsonb, '{"noGym":"Nothing needed.","indoorOnly":"Nothing needed.","limitedTime":"Marking rest is enough.","mobility":"Breathing and gentle range-of-motion work."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('sport', 'custom', 'Your sport', 'Your fixed sport day counts as a higher-intensity session. Warm up well; tomorrow is recovery.', array['sport','running','obstacle','custom']::text[], 'hard', 100, 60, '[]'::jsonb, '{"noGym":"Play as usual.","indoorOnly":"Indoor version of your sport counts.","limitedTime":"Thirty minutes of play counts.","mobility":"Play at the level your body allows today."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('assessment', 'skill', 'Readiness check', 'Easy movement of your choice, then review your baseline, schedule and how your body feels. Not a test.', array['strength','running','walking','hiking','cycling','swimming','obstacle','mobility','custom']::text[], 'easy', 100, 15, '[]'::jsonb, '{"noGym":"A walk counts.","indoorOnly":"Mobility or marching in place counts.","limitedTime":"Ten minutes is enough.","mobility":"Any gentle movement counts."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('trial_prep', 'skill', 'Trial rehearsal', 'Rehearse the skill for your promotion trial at about 70% effort and confirm how you''ll record it.', array['strength','running','walking','hiking','cycling','swimming','obstacle','mobility','custom']::text[], 'easy', 100, 15, '[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}]'::jsonb, '{"noGym":"Rehearse with what you own.","indoorOnly":"Rehearse indoors.","limitedTime":"Ten minutes is enough.","mobility":"Rehearse a modified version."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('trial', 'skill', 'Promotion trial day', 'Warm up, then attempt the trial you chose against your own baseline — good form, no all-out risk. Reschedule if you''re not feeling right.', array['strength','running','walking','hiking','cycling','swimming','obstacle','mobility','custom']::text[], 'moderate', 100, 20, '[]'::jsonb, '{"noGym":"Pick a trial you can do at home.","indoorOnly":"Pick an indoor trial.","limitedTime":"Short trials (push-ups, plank, timed walk) work.","mobility":"Pick a mobility range or supported-strength trial."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
insert into public.session_archetypes (session_type, quest_type, title, description, allowed_activity_types, intensity, factor_pct, fixed_minutes, side, alternatives) values ('event', 'skill', 'Event day', 'This is what you prepared for. Warm up, pace yourself, and log your event.', array['walking','hiking','running','cycling','swimming','obstacle','sport','strength','custom']::text[], 'hard', 100, 60, '[]'::jsonb, '{"noGym":"Log the event as it happened.","indoorOnly":"Log the event as it happened.","limitedTime":"Any part of the event counts.","mobility":"Do what''s safe today; there will be other events."}'::jsonb) on conflict (session_type) do update set quest_type = excluded.quest_type, title = excluded.title, description = excluded.description, allowed_activity_types = excluded.allowed_activity_types, intensity = excluded.intensity, factor_pct = excluded.factor_pct, fixed_minutes = excluded.fixed_minutes, side = excluded.side, alternatives = excluded.alternatives;
